import React,{useState,useEffect,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {StrategyPartCard,StrategyGlyph} from './strategy-part-card.jsx';
import {STRATEGY_ICONS} from './strategy-icons.mjs';
import {StrategyParameterControls,StrategyVariableControl} from './strategy-parameter-controls.jsx';
import {strategyUiSampleGraph,strategyUiGalleryGraph,strategyUiModelGraph,STRATEGY_UI_ROLE_SAMPLES} from './strategy-ui-samples.mjs';
import {decisionNodePortContract} from '../domain/strategy-decision-graph.mjs';
import {STRATEGY_COHORTS,STRATEGY_PORT_TYPE_LABELS} from '../domain/strategy-ontology.mjs';
import {mountStrategyGraphEditor,strategyNumericEdit,strategyParameterConnection,strategyNodeSummary,strategyNodeLabel} from './strategy-graph-editor.jsx';
import {strategyPlanWithGraph} from '../domain/mind-strategy-plan.mjs';

function EditorComparison({model=false}){const host=useRef(null);useEffect(()=>mountStrategyGraphEditor(host.current,{plan:strategyPlanWithGraph(null,(model?strategyUiModelGraph():strategyUiSampleGraph())),name:model?'학습모델 내부 구성 예제':'변수로 조립하는 전략',embedded:true,layoutOnOpen:true,initialFocusNodeId:model?'model':'market'}),[model]);return <section className="strategy-library-comparison"><div className="strategy-library-section-head"><div><h2>{model?'학습모델을 부품으로 열기':'라이브러리 → 실제 편집기'}</h2><p>{model?'카드의 내부 구성 열기 → 특징·조건나무·학습 경로를 편집합니다. 이 예제의 가중치는 동작 설명용입니다.':'동일한 카드·아이콘·변수 입력을 사용하는 편집기입니다. 부품을 선택하고 연결값을 바꿔보세요.'}</p></div><span className="strategy-library-tag">로컬 샘플</span></div><div ref={host} className="strategy-library-editor-host"/></section>;}
function Library(){
 const [tab,setTab]=useState(['cards','icons','editor','models'].includes(location.hash.slice(1))?location.hash.slice(1):'cards'),[graph,setGraph]=useState(strategyUiGalleryGraph),[role,setRole]=useState('ALL'),[state,setState]=useState('DEFAULT'),[query,setQuery]=useState(''),[drafts,setDrafts]=useState({}),[activeValue,setActiveValue]=useState('asset'),[notice,setNotice]=useState('');
 useEffect(()=>{const read=()=>setTab(['cards','icons','editor','models'].includes(location.hash.slice(1))?location.hash.slice(1):'cards');addEventListener('hashchange',read);return()=>removeEventListener('hashchange',read);},[]);
 const patch=(node,value)=>setGraph(g=>({...g,nodes:g.nodes.map(n=>n.id===node.id?{...n,...value}:n)}));
 const data=node=>({node,graph,fieldDrafts:drafts,readOnly:state==='DISABLED',onPatch:patch,onField:(key,value)=>setDrafts(d=>({...d,[key]:value})),onCommit:(n,section,key,id)=>{if(!Object.hasOwn(drafts,id))return;try{patch(n,{config:strategyNumericEdit(n,section,key,drafts[id])});setDrafts(d=>{const copy={...d};delete copy[id];return copy;});setNotice('샘플 값을 변경했습니다.');}catch(e){setNotice(e.message);}},onParameterFocus:id=>{setActiveValue(id);setRole('ALL');setNotice('변수 카드에서 연결값을 편집할 수 있습니다.');},onParameterConnection:(n,field,value)=>{try{setGraph(g=>strategyParameterConnection(g,n.id,field,value));setNotice('샘플 연결을 변경했습니다.');}catch(e){setNotice(e.message);}}});
 return <main className="strategy-library-page"><header className="strategy-library-masthead"><a className="strategy-library-brand" href="/">VIV <span>VIV 디자인 라이브러리</span></a><a href="/icons/strategy/sprite.svg" download="strategy-icons.svg" className="button small">아이콘 SVG 받기</a></header><section className="strategy-library-intro"><h1>전략을 만드는 여덟 가지 부품</h1><p>카드와 아이콘의 역할·상태를 비교하고, 편집기에서 연결을 시험해보세요.</p></section>
 <nav className="strategy-library-tabs" aria-label="디자인 라이브러리"><a href="#cards" aria-current={tab==='cards'?'page':undefined}>카드 <span>8 역할</span></a><a href="#icons" aria-current={tab==='icons'?'page':undefined}>아이콘 <span>{Object.keys(STRATEGY_ICONS).length}</span></a><a href="#editor" aria-current={tab==='editor'?'page':undefined}>편집기 대조</a><a href="#models" aria-current={tab==='models'?'page':undefined}>학습모델</a></nav>
 {tab==='cards'&&<><div className="strategy-library-controls"><label>역할<select aria-label="카드 역할" value={role} onChange={e=>setRole(e.target.value)}><option value="ALL">전체 역할</option>{Object.values(STRATEGY_COHORTS).map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select></label><label>상태<select aria-label="카드 상태" value={state} onChange={e=>setState(e.target.value)}>{[['DEFAULT','기본'],['SELECTED','선택'],['INCOMPLETE','입력 필요'],['INVALID','연결 오류'],['DISABLED','비활성']].map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><button className="button small" onClick={()=>{setGraph(strategyUiGalleryGraph());setDrafts({});setNotice('샘플을 초기화했습니다.');}}>샘플 초기화</button></div><div className="strategy-library-grid">{STRATEGY_UI_ROLE_SAMPLES.filter(s=>role==='ALL'||s.role===role).map(sample=>{const node=graph.nodes.find(n=>n.id===(sample.role==='VALUE'?activeValue:sample.nodeId))??graph.nodes.find(n=>n.id===sample.nodeId);return <article key={sample.role} className="strategy-library-specimen"><div className="strategy-library-specimen-label"><span>{sample.role}</span><span>{STRATEGY_COHORTS[sample.role].label}</span></div><StrategyPartCard node={node} title={node.label??strategyNodeLabel(node)} selected={state==='SELECTED'} connectionState={['INVALID','INCOMPLETE'].includes(state)?state:'VALID'} excluded={state==='DISABLED'} hasParameters={node.type!=='VALUE'} subtitle={sample.description}>{node.type==='VALUE'?<StrategyVariableControl data={data(node)}/>:<StrategyParameterControls data={data(node)} showHandles={false}/>}<dl className="strategy-library-port-summary"><div><dt>입력</dt><dd>{sample.role==='VALUE'?'직접 입력':sample.role==='FLOW'?'조건 · 참 경로 · 거짓 경로':'연결된 자료'}</dd></div><div><dt>출력</dt><dd>{sample.role==='CONDITION'?'참 · 거짓':sample.role==='VALUE'?'공유 변수':sample.role==='EXECUTE'?'실행 요청':decisionNodePortContract(node).outputs.map(p=>STRATEGY_PORT_TYPE_LABELS[p.dataType]??p.dataType).join(' · ')}</dd></div></dl></StrategyPartCard></article>;})}</div></>}
 {tab==='icons'&&<section className="strategy-library-icon-section"><div className="strategy-library-section-head"><div><h2>동작을 구분하는 아이콘</h2><p>24 × 24 그리드 · 2px 선 · 카드, 목록, 도구에서 같은 원본 사용</p></div><input aria-label="아이콘 검색" placeholder="이름 또는 ID 검색" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="strategy-library-icon-grid">{Object.values(STRATEGY_ICONS).filter(i=>(i.id+' '+i.label).toLowerCase().includes(query.toLowerCase())).map(icon=><a key={icon.id} href={'/icons/strategy/'+icon.id+'.svg'} download={icon.id+'.svg'} aria-label={icon.label+' SVG 받기'}><StrategyGlyph id={icon.id}/><strong>{icon.label}</strong><code>{icon.id}</code></a>)}</div></section>}
 {tab==='editor'&&<EditorComparison key="parameters"/>}{tab==='models'&&<EditorComparison key="models" model/>}<p className="strategy-library-notice" role="status">{notice}</p><footer className="strategy-library-footer"><span>카드 · 포트 · 변수 입력 · 상태 · 아이콘</span><span>공용 부품 v1</span></footer></main>;
}
createRoot(document.getElementById('strategy-ui-library')).render(<Library/>);
